import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"运气第十七","description":"杭氏易学 - 运气第十七","frontmatter":{"title":"运气第十七","description":"杭氏易学 - 运气第十七"},"headers":[],"relativePath":"zh/classics/hangshi/018.md","filePath":"zh/classics/hangshi/018.md"}'),l={name:"zh/classics/hangshi/018.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"运气第十七",tabindex:"-1"},[r("运气第十七 "),e("a",{class:"header-anchor",href:"#运气第十七","aria-label":"Permalink to “运气第十七”"},"​")],-1),e("p",null,"运气升降由于气，气之盛衰由于数，数之进退在乎人。圣人作《易》立人极以明人道，言天言地，皆为人言而为人谋。人在天地中，为善为恶，为君子，为小人，皆在人之自为。而气机之感召，阴阳进退，而数即随之而消长。积气成运，积运成象，为殃为祥，皆视所积。积之以渐，非一朝一夕之故。及其至焉，则为泰为否。君子小人之消长，似乎天实为之，命实定之。呜呼！天岂任其责哉！《易》以象设教，善恶吉凶，无不备著于象。而以阴阳五行生合升降，为之节度。法象于天地，而示人以进德修业之天则，各有数度。此君子以人合天之本，而古圣人经纬天地，燮理阴阳之大用，皆备于此焉。后儒不察，空言性命，而莫知其象，莫悉其数。反以圣人示之阴阳气运，为小道，为术数，弃置不言。不知《易》以道阴阳，卦象彖爻无论矣，即孔子之《十翼》，亦无一言无一字，不与阴阳度数相密合。观于纳甲纳音，而后知五运六气，皆出于八卦，在在足与《易》象《易》数相发明。欲知《易》之蕴者，不可不深察焉。",-1),e("p",null,"此主运也。客运则以本年所属五行作初运，轮流而布。",-1),e("p",null,"是为《月令》之气，年年定局不易，谓之主气。至于客气，则从年司天，自正南位起轮布，看主与客相临，其气相得则和，不相得则害。",-1),e("p",null,"五运六气，天地阴阳之橐龠，其传最古，今惟《内经》言之最详。圣人作《易》，法象乎天地，近取诸身，远取诸物。而天地万物，皆范围乎运气之中。所谓造化之机，与吾人身心性命，息息相关。民胞物与，岂空言所济！读董子《春秋繁露》、《淮南鸿烈》、扬子《法言》，当知鄙言之非妄也。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
